<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/bootstrap.php';
require __DIR__.'/surf-beta-engine.php';
$pdo=cc_db();if(!$pdo){fwrite(STDERR,"DB unavailable\n");exit(1);}
$pdo->exec("CREATE TABLE IF NOT EXISTS surf_beta_subscribers (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,confirmed TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,profile_json MEDIUMTEXT NOT NULL,email_frequency ENUM('morning','evening','both') NOT NULL DEFAULT 'morning',origin_lat DECIMAL(8,3) NULL,origin_lon DECIMAL(8,3) NULL,last_email_at DATETIME NULL,last_morning_date DATE NULL,last_evening_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
function sb_secret(): string {$c=cc_config();return hash('sha256','surf-beta-v2|'.($c['db_pass']??'fallback').'|costacams');}
function sb_token(int $id,string $email,string $purpose): string {$sig=hash_hmac('sha256',$id.'|'.$purpose.'|'.strtolower($email),sb_secret());return rtrim(strtr(base64_encode($id.'|'.$purpose.'|'.$sig),'+/','-_'),'=');}
function sb_mail(string $to,string $subject,string $html): bool {$h="MIME-Version: 1.0\r\nContent-type: text/html; charset=UTF-8\r\nFrom: CostaCams <support@costacams.com>\r\nReply-To: support@costacams.com\r\n";return @mail($to,$subject,$html,$h);}
function sb_uv_text(float $u): string {if($u<3)return 'UV low';if($u<6)return 'UV moderate — SPF50+ recommended for the water';if($u<8)return 'UV high — SPF50+ water-resistant + UPF rashie';if($u<11)return 'UV very high — maximum sun protection';return 'UV extreme — strongly limit unnecessary exposure';}
$tz=new DateTimeZone('Australia/Brisbane');$now=new DateTimeImmutable('now',$tz);$hm=(int)$now->format('Hi');$date=$now->format('Y-m-d');
$doMorning=$hm>=415&&$hm<500;$doEvening=$hm>=1900&&$hm<1945;if(!$doMorning&&!$doEvening){echo "outside_send_window\n";exit;}
$spots=cc_surf_load_spots($pdo);$rows=$pdo->query("SELECT * FROM surf_beta_subscribers WHERE confirmed=1 AND active=1")->fetchAll();$sent=0;$failed=0;$base='https://costacams.com/ccdeploy-v3/costacams-v3/surf-match-beta-v3.php';
foreach($rows as $r){$freq=(string)$r['email_frequency'];$kind=$doMorning?'morning':'evening';if($freq!==$kind&&$freq!=='both')continue;$last=$doMorning?(string)($r['last_morning_date']??''):(string)($r['last_evening_date']??'');if($last===$date)continue;
 $p=json_decode((string)$r['profile_json'],true);if(!is_array($p))$p=cc_surf_profile_defaults();$p=array_replace(cc_surf_profile_defaults(),$p);if($r['origin_lat']!==null&&$r['origin_lon']!==null){$p['origin_lat']=(float)$r['origin_lat'];$p['origin_lon']=(float)$r['origin_lon'];}$p['day_offset']=$doMorning?0:1;$epoch=cc_surf_selected_epoch($p);$rank=cc_surf_rank($spots,$p,$epoch);if(!$rank)continue;$top=array_slice($rank,0,3);$a=$top[0];$h=$a['hour'];$travel=$a['travel_minutes'];$timeLabel=(new DateTimeImmutable('@'.$a['eval_epoch']))->setTimezone($tz)->format('g:i A');$travelLine='';if($travel!==null){if(($p['time_mode']??'arrive')==='arrive'){$leave=(new DateTimeImmutable('@'.$epoch))->setTimezone($tz)->modify('-'.$travel.' minutes')->format('g:i A');$travelLine='<p><b>Leave around '.$leave.'</b> · estimated drive ~'.$travel.' min.</p>';}else{$arr=(new DateTimeImmutable('@'.$epoch))->setTimezone($tz)->modify('+'.$travel.' minutes')->format('g:i A');$travelLine='<p><b>Estimated arrival '.$arr.'</b> · drive ~'.$travel.' min.</p>';}}
 $manage=$base.'?manage='.rawurlencode(sb_token((int)$r['id'],(string)$r['email'],'manage'));$unsub=$base.'?unsubscribe='.rawurlencode(sb_token((int)$r['id'],(string)$r['email'],'unsubscribe'));
 $rowsHtml='';foreach($top as $i=>$x){$hh=$x['hour'];$rowsHtml.='<tr><td style="padding:8px;border-bottom:1px solid #e5e7e8">#'.($i+1).' <b>'.htmlspecialchars((string)$x['spot']['name']).'</b></td><td style="padding:8px;border-bottom:1px solid #e5e7e8">'.(int)$x['score'].'/100</td><td style="padding:8px;border-bottom:1px solid #e5e7e8">'.number_format((float)($hh['wave_height']??0),1).'m · '.round((float)($hh['wave_period']??0)).'s · '.htmlspecialchars((string)($hh['wind_compass']??'—')).' '.round((float)($hh['wind_speed']??0)).'km/h</td></tr>';}
 $dayWord=$doMorning?'today':'tomorrow';$subject='CostaCams Surf Brief: best match '.$dayWord.' — '.$a['spot']['name'];$html='<div style="font-family:Arial,sans-serif;max-width:650px;margin:auto;color:#182126"><p style="font-size:12px;color:#397b8b;font-weight:bold">COSTACAMS SURF BRIEF · '.strtoupper($dayWord).'</p><h1 style="margin-bottom:4px">'.$a['spot']['name'].' · '.$a['score'].'/100</h1><p style="margin-top:0;color:#667">Best match around '.$timeLabel.' for your saved surf profile.</p><p>🌊 '.number_format((float)($h['wave_height']??0),1).' m · '.round((float)($h['wave_period']??0)).' s &nbsp; ⚡ '.number_format((float)($h['energy_kwm']??0),1).' kW/m &nbsp; 💨 '.htmlspecialchars((string)($h['wind_compass']??'—')).' '.round((float)($h['wind_speed']??0)).' km/h</p><p>☀️ UV '.number_format((float)($h['uv']??0),1).' — '.htmlspecialchars(sb_uv_text((float)($h['uv']??0))).'</p>'.$travelLine.'<table style="border-collapse:collapse;width:100%;margin:15px 0">'.$rowsHtml.'</table><p><a style="display:inline-block;background:#0d6578;color:#fff;text-decoration:none;padding:11px 16px;border-radius:8px" href="'.htmlspecialchars($manage).'">Open & adjust my Surf Match</a></p><p style="font-size:11px;color:#778">Forecast/model guidance only. Check local conditions, lifeguards and your own ability before entering the water.</p><p style="font-size:11px"><a href="'.htmlspecialchars($manage).'">Edit profile</a> · <a href="'.htmlspecialchars($unsub).'">Unsubscribe</a></p></div>';
 if(sb_mail((string)$r['email'],$subject,$html)){$field=$doMorning?'last_morning_date':'last_evening_date';$pdo->prepare("UPDATE surf_beta_subscribers SET $field=?,last_email_at=NOW() WHERE id=?")->execute([$date,(int)$r['id']]);$sent++;}else{$failed++;}
}
echo "surf_brief kind=".($doMorning?'morning':'evening')." sent=$sent failed=$failed\n";